"""Working demo for this book record: full reader + HTML exporter.
Run:  python3 book_demo.py              (prints the whole book)
      python3 book_demo.py 3            (prints chapter 3 only)
      python3 book_demo.py search WORD  (finds WORD across chapters)
      python3 book_demo.py html         (writes book.html)
"""
import json, sys, html as _h

BOOK = {'title': 'Starlight and a silver acorn', 'author': 'Signature original', 'genre': 'Bedtime Magic', 'chapters': [{'n': 1, 'title': 'The Finding', 'text': "That night the Thorn Witch's shadow fell over the Moonlit Meadow: the brook ran backwards, the mushrooms glowed red, the stars went out one by one. Ember held a silver acorn tight. It pulsed, warm as a heartbeat.\n\n'We have to fix this,' Ember said. a loyal dog nodded, brave and small. 'The stories say a silver acorn can. The stories also say it's dangerous.' Ember grinned. 'The best things are.'\n\nEmber found a silver acorn on the first day of spring, under the oldest oak in the Moonlit Meadow, where the fireflies danced like sparks. It glowed. Things that glow, Ember's grandmother always said, are either magic or trouble. Often both."}, {'n': 2, 'title': 'The Journey', 'text': "the Thorn Witch's minions — shadow crows with eyes like coals — attacked at the hollow hill. a loyal dog was so brave that Ember nearly cried: small teeth, loud courage, and a plan involving the singing shell — no, a silver acorn — and perfect timing.\n\nThe path through the Moonlit Meadow was a storybook: a brook that sang, mushrooms that lit the way, an oak that bowed. a loyal dog knew every tale and told them walking, which made the miles shorter and the dark less dark.\n\nAt the edge of the Moonlit Meadow, they looked back at the darkened woods and forward at the Thorn Witch's thorn castle. 'Together?' Ember asked. 'Always,' said a loyal dog. And in they went."}, {'n': 3, 'title': 'The Thorn Castle', 'text': "Inside, everything was grey: grey tapestries, grey servants, a grey throne where the Thorn Witch sat, holding the stolen starlight of the Moonlit Meadow in a jar. 'Mine,' the Thorn Witch hissed. 'All mine.'\n\nEmber held up a silver acorn. 'Not this,' Ember said. 'This chose me.' the Thorn Witch laughed — a sound like dead leaves — and sent the shadow crows. a loyal dog met them with the owl's feather and total fearlessness.\n\nThe battle was strange and wonderful: a silver acorn's light against the Thorn Witch's dark, Ember's courage against the Thorn Witch's spite, a loyal dog's loyalty against everything. Light, it turns out, is very stubborn."}, {'n': 4, 'title': 'Starlight Restored', 'text': "the Thorn Witch's grumble was kept in a jar on the mantel, as a reminder. On quiet nights it mutters. Ember finds it comforting: proof that dark can be made small, and kept.\n\nlove breaks every spell — Ember wrote it in the family book, under the date, in the careful letters of someone who means it forever.\n\nthe Moonlit Meadow celebrated: the fireflies spelled Ember's name, the oak dropped acorns of thanks, the wise owl composed a ballad with a loyal dog as the hero — a loyal dog insisted Ember was the hero; they compromised on both."}, {'n': 5, 'title': 'The Promise Kept', 'text': "Ember grew, as heroes do, but never grew out of the Moonlit Meadow. Every spring they check the old oak. Every night a silver acorn glows. Every tale a loyal dog tells starts, 'When we saved the stars...'\n\nNew children come to hear the story, and Ember tells it true: the fear, the laughter, the moment it almost went wrong. 'Were you scared?' they ask. 'Terrified,' Ember says. 'That's what brave is.'\n\na loyal dog is older now, greyer, no less brave. They still walk together, still argue about the ballad, still keep the grumble-jar dusted. Friendship, like starlight, doesn't fade if you tend it."}, {'n': 6, 'title': 'Bedtime', 'text': "'Again,' says the listener. It is always 'again.' The best stories are.\n\nAnd now it's bedtime in the Moonlit Meadow, and a silver acorn glows soft, and a loyal dog is telling the story one more time, to one more sleepy listener. 'The end,' a loyal dog says.\n\nEmber smiles from the doorway. Outside, the stars are out — all of them, every one, back where they belong. The brook sings. The fireflies dance."}]}

def word_count():
    return sum(len(c["text"].split()) for c in BOOK["chapters"])

def print_book(ch=None):
    print("=" * 64)
    print(BOOK["title"].upper(), "\nby", BOOK["author"], "-", BOOK["genre"])
    print("=" * 64)
    for c in BOOK["chapters"]:
        if ch and c["n"] != ch:
            continue
        print("\n\nCHAPTER %d: %s\n%s" % (c["n"], c["title"], "-" * 40))
        print(c["text"])
    print("\n[%d words, %d chapters — complete]" % (word_count(), len(BOOK["chapters"])))

def search(word):
    w = word.lower()
    for c in BOOK["chapters"]:
        for i, para in enumerate(c["text"].split("\n\n")):
            if w in para.lower():
                print("[ch %d, para %d] %s..." % (c["n"], i + 1, para[:160].replace("\n", " ")))

def write_html(path="book.html"):
    parts = ["<html><head><meta charset='utf-8'><title>%s</title></head><body>" % _h.escape(BOOK["title"])]
    parts.append("<h1>%s</h1><p><i>by %s — %s</i></p>" % (_h.escape(BOOK["title"]), _h.escape(BOOK["author"]), _h.escape(BOOK["genre"])))
    for c in BOOK["chapters"]:
        parts.append("<h2>Chapter %d: %s</h2>" % (c["n"], _h.escape(c["title"])))
        for para in c["text"].split("\n\n"):
            parts.append("<p>%s</p>" % _h.escape(para))
    parts.append("</body></html>")
    open(path, "w").write("\n".join(parts))
    print("wrote", path)

if __name__ == "__main__":
    a = sys.argv[1:]
    if a and a[0] == "html":
        write_html()
    elif len(a) >= 2 and a[0] == "search":
        search(a[1])
    elif a and a[0].isdigit():
        print_book(int(a[0]))
    else:
        print_book()

